'use client';

import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { cx } from '@/utils/cx';

const layoutProperties = new Set([
  'height', 'block-size', 'min-height', 'max-height', 'min-block-size', 'max-block-size',
  'width', 'inline-size', 'min-width', 'max-width', 'min-inline-size', 'max-inline-size',
  'padding-top', 'padding-bottom', 'padding-left', 'padding-right', 'padding-block-start', 'padding-block-end',
  'margin-top', 'margin-bottom', 'margin-left', 'margin-right', 'margin-block-start', 'margin-block-end',
  'border-top-width', 'border-bottom-width', 'gap', 'row-gap', 'column-gap', 'grid-template-rows', 'grid-template-columns', 'flex-basis', 'font-size', 'line-height', 'letter-spacing',
]);

/** Animate real layout height so adjacent content follows without being scaled. */
export function AnimatedHeight({ children, className }: { children: ReactNode; className?: string }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frame = frameRef.current;
    const content = contentRef.current;
    if (!frame || !content) return;
    // Start at the natural size, including when server-rendered content is nonempty.
    frame.style.transition = 'none';
    frame.style.height = `${content.offsetHeight}px`;
    void frame.offsetHeight;
    frame.style.removeProperty('transition');
    let alive = true;
    const observed = new WeakSet<Animation>();
    const affectsLayout = (animation: Animation) => {
      if (animation.playState !== 'running') return false;
      if ('transitionProperty' in animation) return layoutProperties.has(String(animation.transitionProperty));
      return animation.effect instanceof KeyframeEffect && animation.effect.getKeyframes().some(frame =>
        Object.keys(frame).some(property => layoutProperties.has(property.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)))
      );
    };
    const nestedLayoutIsMoving = () => content.getAnimations({subtree: true}).some(affectsLayout);
    const restore = () => { if (alive && !nestedLayoutIsMoving()) frame.style.removeProperty('transition'); };
    const observeMotion = () => {
      const moving = content.getAnimations({subtree: true}).filter(affectsLayout);
      for (const animation of moving) if (!observed.has(animation)) {
        observed.add(animation);
        animation.finished.then(restore, restore);
      }
      return moving.length > 0;
    };
    const restoreTransition = (event: TransitionEvent) => {
      if (layoutProperties.has(event.propertyName)) restore();
    };
    content.addEventListener('transitionend', restoreTransition);
    content.addEventListener('transitioncancel', restoreTransition);
    const observer = new ResizeObserver(([entry]) => {
      const height = entry.borderBoxSize?.[0]?.blockSize ?? content.offsetHeight;
      // A child can already be animating its real height. Follow that geometry
      // directly, so nested frames do not each add another full transition.
      const following = observeMotion();
      if (following) frame.style.transition = 'none';
      else frame.style.removeProperty('transition');
      frame.style.height = `${height}px`;
    });
    // Helper text and disclosure spacing can change without changing the
    // content box. Observe the same border box that supplies the target height.
    observer.observe(content, { box: 'border-box' });
    return () => {
      alive = false;
      observer.disconnect();
      content.removeEventListener('transitionend', restoreTransition);
      content.removeEventListener('transitioncancel', restoreTransition);
    };
  }, []);
  return <div ref={frameRef} className={cx('ui-animated-height', className)}><div ref={contentRef} className="ui-animated-height__content">{children}</div></div>;
}

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

import type { ButtonHTMLAttributes, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CloseButtonSize = '2xs' | 'xs' | 'sm' | 'md';

export type CloseButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'> & {
  size?: CloseButtonSize;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

const glyphSizes: Record<CloseButtonSize, number> = { '2xs': 8, xs: 11, sm: 13, md: 17 };
const strokes: Record<CloseButtonSize, number> = { '2xs': 1.6, xs: 2, sm: 2, md: 2.5 };

export function CloseButton({ size = 'xs', className, type = 'button', ...props }: CloseButtonProps) {
  const glyph = glyphSizes[size];
  const inset = size === '2xs' ? 1.4 : 2;
  return (
    <button type={type} data-size={size} className={cx('ui-close-button', className)} {...props}>
      <svg width={glyph} height={glyph} viewBox={`0 0 ${glyph} ${glyph}`} fill="none" aria-hidden="true">
        <path d={`M${inset} ${inset}L${glyph - inset} ${glyph - inset}M${glyph - inset} ${inset}L${inset} ${glyph - inset}`} stroke="currentColor" strokeWidth={strokes[size]} strokeLinecap="round" />
      </svg>
    </button>
  );
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import { RiCheckLine, RiErrorWarningLine } from '@remixicon/react';
import { Button } from '@/components/base/buttons/button';
import { useMotionTokens } from '@/hooks/use-motion-tokens';
import { cx } from '@/utils/cx';

export type StepperStep = { id: string; label: string; description?: string; controls?: string; status?: 'pending' | 'complete' | 'error'; isOptional?: boolean; isDisabled?: boolean };
export type StepperProps = {
  steps: StepperStep[];
  selectedKey?: string;
  defaultSelectedKey?: string;
  onSelectionChange?: (key: string) => void;
  variant?: 'numbered' | 'labels';
  orientation?: 'horizontal' | 'vertical';
  isReadOnly?: boolean;
  className?: string;
  'aria-label'?: string;
};

/** Selection describes location; only caller-supplied status describes completion. */
export function Stepper({ steps, selectedKey, defaultSelectedKey, onSelectionChange, variant = 'numbered', orientation = 'horizontal', isReadOnly = false, className, 'aria-label': label = 'Progress steps' }: StepperProps) {
  const [internal, setInternal] = useState(defaultSelectedKey ?? steps.find(step => !step.isDisabled)?.id ?? '');
  const [focused, setFocused] = useState<string | null>(null);
  const selected = selectedKey ?? internal;
  const enabled = steps.filter(step => !step.isDisabled);
  const tabStop = enabled.find(step => step.id === focused)?.id ?? enabled.find(step => step.id === selected)?.id ?? enabled[0]?.id;
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const id = useId(), reduced = useReducedMotion(), root = useRef<HTMLElement>(null), tokens = useMotionTokens(root);
  const geometry = JSON.stringify(steps.map(step => [step.id, step.label, step.description, step.isOptional]));
  useLayoutEffect(() => {
    const element = root.current;
    if (!element || variant === 'labels') return;
    const items = [...element.querySelectorAll<HTMLElement>('.ui-stepper__item')];
    function measure() {
      const rtl = getComputedStyle(element!).direction === 'rtl';
      const marks = items.map(item => item.querySelector<HTMLElement>('.ui-stepper__mark')!.getBoundingClientRect());
      items.forEach((item, index) => {
        const mark = marks[index], next = marks[index + 1], box = item.getBoundingClientRect();
        if (!next) return;
        const vertical = Math.abs(next.top - mark.top) > Math.abs(next.left - mark.left);
        const center = mark.left + mark.width / 2, nextCenter = next.left + next.width / 2;
        const inlineCenter = rtl ? box.right - center : center - box.left;
        item.style.setProperty('--step-line-inline', `${vertical ? inlineCenter : inlineCenter + 21}px`);
        item.style.setProperty('--step-line-top', `${mark.top - box.top + mark.height / 2 + (vertical ? 21 : 0)}px`);
        item.style.setProperty('--step-line-width', `${vertical ? 1 : Math.max(0, (rtl ? center - nextCenter : nextCenter - center) - 42)}px`);
        item.style.setProperty('--step-line-height', `${vertical ? Math.max(0, next.top - mark.top - 42) : 1}px`);
      });
    }
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element, {box:'border-box'});
    items.forEach(item => observer.observe(item, {box:'border-box'}));
    element.querySelectorAll('.ui-stepper__content').forEach(content => observer.observe(content, {box:'border-box'}));
    const direction = new MutationObserver(measure);
    for (let parent: HTMLElement | null = element; parent; parent = parent.parentElement) direction.observe(parent, {attributes:true, attributeFilter:['dir','class']});
    return () => { observer.disconnect(); direction.disconnect(); };
  }, [geometry, orientation, variant]);
  function choose(key: string) {
    if (isReadOnly || key === selected || !enabled.some(step => step.id === key)) return;
    if (selectedKey === undefined) setInternal(key);
    onSelectionChange?.(key);
  }
  function navigate(event: KeyboardEvent<HTMLElement>) {
    if (isReadOnly || event.altKey || event.ctrlKey || event.metaKey || !['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key) || !enabled.length) return;
    const key = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-step-key]')?.dataset.stepKey;
    if (!key) return;
    event.preventDefault();
    const current = enabled.findIndex(step => step.id === key);
    const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
    const forward = event.key === 'ArrowDown' || (event.key === 'ArrowRight' && !rtl) || (event.key === 'ArrowLeft' && rtl);
    const index = event.key === 'Home' ? 0 : event.key === 'End' ? enabled.length - 1 : (current + (forward ? 1 : -1) + enabled.length) % enabled.length;
    buttons.current.get(enabled[index].id)?.focus();
  }
  return <nav ref={root} className={cx('ui-stepper', className)} data-variant={variant} data-orientation={orientation} data-readonly={isReadOnly || undefined} aria-label={label} onKeyDown={navigate}>
    <ol className="ui-stepper__list">{steps.map((step, index) => {
      const current = selected === step.id, status = step.status ?? 'pending', detailId = `${id}-${index}`;
      const content = <><span className="ui-stepper__content"><span className="ui-stepper__mark" aria-hidden>{(['pending','complete','error'] as const).map(kind => <span className="ui-stepper__glyph" key={kind} data-status={kind} data-active={status === kind || undefined}>{kind === 'complete' ? <RiCheckLine/> : kind === 'error' ? <RiErrorWarningLine/> : index + 1}</span>)}</span><span className="ui-stepper__copy"><span className="ui-stepper__title">{step.label}</span>{step.isOptional && <span className="ui-stepper__optional">Optional</span>}{step.description && <span className="ui-stepper__description">{step.description}</span>}</span></span>{variant === 'labels' && current && <motion.span className="ui-stepper__indicator" layoutId={`${id}-step`} transition={{ duration: reduced ? 0 : tokens.standard, ease: tokens.ease }}/>}</>;
      return <li key={step.id} className="ui-stepper__item" data-current={current || undefined} data-status={status} data-disabled={step.isDisabled || undefined}>
        {isReadOnly ? <div className="ui-stepper__control" aria-current={current ? 'step' : undefined} aria-describedby={detailId}>{content}</div> : <Button ref={element => { if (element) buttons.current.set(step.id, element); else buttons.current.delete(step.id); }} variant="ghost" size="small" className="ui-stepper__control" data-step-key={step.id} tabIndex={tabStop === step.id ? 0 : -1} disabled={step.isDisabled} aria-label={step.label} aria-describedby={detailId} aria-controls={step.controls} aria-current={current ? 'step' : undefined} onFocus={() => setFocused(step.id)} onBlur={event => { if (!event.currentTarget.closest('.ui-stepper')?.contains(event.relatedTarget)) setFocused(null); }} onClick={() => choose(step.id)}>{content}</Button>}
        <span id={detailId} className="sr-only">Step {index + 1} of {steps.length}.{current ? ' Current step.' : ''}{status === 'complete' ? ' Complete.' : status === 'error' ? ' Needs attention.' : ''}{step.isOptional ? ' Optional.' : ''}{step.isDisabled ? ' Unavailable.' : ''}{step.description ? ` ${step.description}` : ''}</span>
      </li>;
    })}</ol>
  </nav>;
}

'use client';

import { useEffect, useId, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { AnimatePresence, motion, useIsPresent, useReducedMotion } from 'motion/react';
import { RiCheckLine } from '@remixicon/react';
import { AnimatedHeight } from '@/components/base/animated-height/animated-height';
import { Button } from '@/components/base/buttons/button';
import { CloseButton } from '@/components/base/buttons/close-button';
import { Stepper } from '@/components/base/stepper/stepper';
import { cx } from '@/utils/cx';

export type Question = {
  id: string;
  prompt: string;
  type: 'single' | 'multiple';
  options: { id: string; label: string; description?: string }[];
  allowOther?: boolean;
  stepLabel?: string;
};

export type QuestionnaireProps = {
  questions: Question[];
  value?: Record<string, string[]>;
  defaultValue?: Record<string, string[]>;
  onChange?: (answers: Record<string, string[]>) => void;
  onComplete?: (answers: Record<string, string[]>, otherAnswers: Record<string, string>) => void;
  onClose?: () => void;
  advanceDelay?: number;
  className?: string;
};

const slideVariants = {
  enter: (travel: number) => ({ opacity: 0, x: travel * 18, filter: 'blur(3px)' }),
  center: { opacity: 1, x: 0, filter: 'blur(0px)' },
  exit: (travel: number) => ({ opacity: 0, x: travel * -18, filter: 'blur(3px)' }),
};

function QuestionPresence({ children }: { children: ReactNode }) {
  const present = useIsPresent();
  return <div inert={!present} aria-hidden={!present || undefined}>{children}</div>;
}

export function Questionnaire({ questions, value, defaultValue = {}, onChange, onComplete, onClose, advanceDelay = 180, className }: QuestionnaireProps) {
  const [internal, setInternal] = useState(defaultValue);
  const [index, setIndex] = useState(0);
  const [direction, setDirection] = useState(1);
  const [otherAnswers, setOtherAnswers] = useState<Record<string, string>>({});
  const advanceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const id = useId();
  const reducedMotion = useReducedMotion();
  const answers = value ?? internal;
  const question = questions[index];
  const root = useRef<HTMLDivElement>(null), focusQuestion = useRef(false);
  useLayoutEffect(() => {
    if (!focusQuestion.current) return;
    focusQuestion.current = false;
    [...(root.current?.querySelectorAll<HTMLElement>('.ui-questionnaire__question h2') ?? [])].find(title => !title.closest('[inert]'))?.focus({ preventScroll: true });
  }, [question?.id]);

  useEffect(() => () => { if (advanceTimer.current) clearTimeout(advanceTimer.current); }, []);
  if (!question) return null;

  function update(next: Record<string, string[]>) {
    if (value === undefined) setInternal(next);
    onChange?.(next);
  }

  function goTo(step: number, moveFocus = false) {
    if (advanceTimer.current) clearTimeout(advanceTimer.current);
    advanceTimer.current = null;
    if (step < 0 || step >= questions.length || step === index) return;
    focusQuestion.current = moveFocus;
    setDirection(step > index ? 1 : -1);
    setIndex(step);
  }

  function toggle(option: string) {
    if (advanceTimer.current) clearTimeout(advanceTimer.current);
    advanceTimer.current = null;
    const current = answers[question.id] ?? [];
    const selected = current.includes(option);
    const next = question.type === 'single'
      ? [option]
      : selected ? current.filter(id => id !== option) : [...current, option];
    update({ ...answers, [question.id]: next });
    if (question.type === 'single' && option !== 'other' && index < questions.length - 1) {
      advanceTimer.current = setTimeout(() => goTo(index + 1, true), advanceDelay);
    }
  }

  function changeOther(text: string) {
    setOtherAnswers(current => ({ ...current, [question.id]: text }));
    const current = answers[question.id] ?? [];
    if (text && !current.includes('other')) {
      update({ ...answers, [question.id]: question.type === 'single' ? ['other'] : [...current, 'other'] });
    }
  }

  function next() {
    if (index < questions.length - 1) goTo(index + 1, true);
    else onComplete?.(answers, otherAnswers);
  }

  const selected = answers[question.id] ?? [];
  return <div ref={root} className={cx('ui-questionnaire', className)} role="group" aria-label="Questionnaire">
    {onClose && <CloseButton className="ui-questionnaire__close" size="xs" aria-label="Dismiss" onClick={onClose}/>}
    <AnimatedHeight><div id={`${id}-questions`} role="region" aria-label={question.prompt}><AnimatePresence mode="popLayout" initial={false} custom={direction}>
      <motion.div key={question.id} className="ui-questionnaire__question" custom={direction} variants={slideVariants} initial={reducedMotion ? false : 'enter'} animate="center" exit={reducedMotion ? undefined : 'exit'} transition={{ duration: reducedMotion ? 0 : .22, ease: [0.2, .75, .25, 1] }}>
        <QuestionPresence>
        <h2 tabIndex={-1}>{question.prompt}</h2>
        <div className="ui-questionnaire__options" role="group" aria-label={question.prompt}>
          {question.options.map(option => <label key={option.id} data-selected={selected.includes(option.id) || undefined}>
            <input className="ui-questionnaire__choice" type={question.type === 'single' ? 'radio' : 'checkbox'} name={`${id}-${question.id}`} value={option.id} checked={selected.includes(option.id)} onChange={() => toggle(option.id)} />
            <span className="ui-questionnaire__option-copy"><strong>{option.label}</strong>{option.description && <small>{option.description}</small>}</span>
            <span className="ui-questionnaire__check" aria-hidden><RiCheckLine size={12} /></span>
          </label>)}
          {question.allowOther && <div className="ui-questionnaire__other-row" data-selected={selected.includes('other') || undefined}>
            <div className="ui-questionnaire__option-copy"><strong>Other</strong><input className="ui-questionnaire__other" aria-label="Other answer" value={otherAnswers[question.id] ?? ''} placeholder="Enter your custom answer here" onFocus={() => { if (!selected.includes('other')) toggle('other'); }} onChange={event => changeOther(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); next(); } }} /></div>
            <label className="ui-questionnaire__other-check" aria-label="Select Other"><input className="ui-questionnaire__choice" type={question.type === 'single' ? 'radio' : 'checkbox'} name={`${id}-${question.id}`} value="other" checked={selected.includes('other')} onChange={() => toggle('other')} /><span className="ui-questionnaire__check" aria-hidden><RiCheckLine size={12} /></span></label>
          </div>}
        </div>
        </QuestionPresence>
      </motion.div>
    </AnimatePresence></div></AnimatedHeight>
    <footer><Stepper className="ui-questionnaire__steps" aria-label="Steps" variant="labels" selectedKey={question.id} onSelectionChange={key => goTo(questions.findIndex(item => item.id === key))} steps={questions.map((item, step) => ({ id: item.id, label: item.stepLabel ?? `Step ${step + 1}`, controls: `${id}-questions`, status: (answers[item.id] ?? []).some(answer => answer === 'other' ? Boolean(otherAnswers[item.id]?.trim()) : item.options.some(option => option.id === answer)) ? 'complete' : 'pending' }))}/><Button size="small" variant="secondary" disabled={index === 0} onClick={() => goTo(index - 1, true)}>Previous</Button><Button size="small" variant="solid" className="ui-questionnaire__next" onClick={next}>{index === questions.length - 1 ? 'Done' : 'Next'}</Button></footer>
  </div>;
}

'use client';

import {useLayoutEffect,useState,type RefObject} from 'react';

export type MotionTokens={fast:number;standard:number;settle:number;ease:[number,number,number,number]};
const defaults:MotionTokens={fast:.16,standard:.24,settle:.36,ease:[.2,.75,.25,1]};
function seconds(value:string,fallback:number){const match=value.trim().match(/^([\d.]+)(ms|s)$/);if(!match)return fallback;const amount=Number(match[1])/(match[2]==='ms'?1000:1);return Number.isFinite(amount)&&amount>=0?amount:fallback;}

/** Use the same scoped CSS tokens for JavaScript layout/glyph animation. */
export function useMotionTokens(scope?:RefObject<Element|null>){
  const [tokens,setTokens]=useState<MotionTokens>(defaults);
  useLayoutEffect(()=>{
    const element=scope?.current??document.documentElement;
    function read(){
      const style=getComputedStyle(element),curve=style.getPropertyValue('--motion-ease').match(/^\s*cubic-bezier\(([^)]+)\)/)?.[1].split(',').map(Number);
      const ease=curve?.length===4&&curve.every(Number.isFinite)?curve as MotionTokens['ease']:defaults.ease;
      const next={fast:seconds(style.getPropertyValue('--motion-fast'),defaults.fast),standard:seconds(style.getPropertyValue('--motion-standard'),defaults.standard),settle:seconds(style.getPropertyValue('--motion-settle'),defaults.settle),ease};
      setTokens(current=>current.fast===next.fast&&current.standard===next.standard&&current.settle===next.settle&&current.ease.every((value,index)=>value===next.ease[index])?current:next);
    }
    read();const observer=new MutationObserver(read);
    observer.observe(document.documentElement,{attributes:true,attributeFilter:['style','class','data-accent']});
    if(element!==document.documentElement)observer.observe(element,{attributes:true,attributeFilter:['style','class']});
    return()=>observer.disconnect();
  },[scope]);
  return tokens;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
